mapper.select:
SELECT DISTINCT p.id, p.permission_name, p.permission_code, p.display_name, p.resource, p.action, COALESCE(rp.scope_override, p.scope) as scope, p.resource_type, p.resource_path, p.http_method, p.description, p.status, p.created_at, p.updated_at FROM permissions p INNER JOIN role_permissions rp ON p.id = rp.permission_id INNER JOIN roles r ON rp.role_id = r.id INNER JOIN user_roles ur ON r.id = ur.role_id WHERE ur.user_id = #{userId}
AND (ur.tenant_id = #{tenantId} OR ur.tenant_id IS NULL)
AND r.status = 'ACTIVE' AND p.status = 'ACTIVE' AND (ur.effective_from IS NULL OR ur.effective_from <= CURRENT_DATE) AND (ur.effective_to IS NULL OR ur.effective_to >= CURRENT_DATE) ORDER BY p.resource, p.action
